
from typing_extensions import Annotated, List, TypedDict, Sequence
from langchain_core.messages import BaseMessage
from langgraph.graph.message import add_messages
from ...common import BaseRequestModel


class DiscoveryTopicQuestionsWriterAgentRequest(BaseRequestModel):
    input: str
    topic: str
    target: str

class DiscoveryTopicQuestionsWriterOutput(BaseRequestModel):
    topic: str
    questions: Annotated[
        List[str],
        ...,
        "The questions generated by the agent"
    ]

class DiscoveryState(TypedDict):
    input: str
    topic: str
    chat_history: Annotated[Sequence[BaseMessage], add_messages]
    context: str
    answer: str
    target: str
    questions: Annotated[
        List[str], 
        ...,
        "The questions generated by the agent"]
    sources: Annotated[
        List[str],
        ...,
        "List of sources used to answer the question in JSON format.  Ensure that the page number is labeled 'pageNumber'.  If there are a range of page numbers, create a separate list item for each page number."
    ]